    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateConvention>>, TError,UpdateConventionMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof updateConvention>>, TError,UpdateConventionMutationVariables, TContext> => {

const mutationKey = getUpdateConventionMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof updateConvention>>, UpdateConventionMutationVariables> = (props) => {
          const {id,data} = props ?? {};

          return  updateConvention(id,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type UpdateConventionMutationResult = NonNullable<Awaited<ReturnType<typeof updateConvention>>>
    export type UpdateConventionMutationBody = BodyType<ConventionUpdate>
    export type UpdateConventionMutationError = ErrorType<Erreur>
    export type UpdateConventionMutationVariables = {id: number;data: BodyType<ConventionUpdate>}

    /**
 * @summary Mettre à jour une convention
 */
export const useUpdateConvention = <TError = ErrorType<Erreur>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateConvention>>, TError,UpdateConventionMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof updateConvention>>,
        TError,
        UpdateConventionMutationVariables,
        TContext
      > => {
      return useMutation(getUpdateConventionMutationOptions(options));
    }

export const getDeleteConventionUrl = (id: number,
    params: DeleteConventionParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/conventions/${id}?${stringifiedParams}` : `/api/conventions/${id}`
}

/**
 * @summary Supprimer une convention
 */
export const deleteConvention = async (id: number,
    params: DeleteConventionParams, options?: Parameters<typeof customFetch>[1]): Promise<void> => {

  return customFetch<void>(getDeleteConventionUrl(id,params),
  {
    ...options,
    method: 'DELETE'


  }
);}





